function ProviderLogo({family}:{family:string}){const slug=family.toLowerCase().replace(/[^a-z]/g,'');return <span className={'provider-logo provider-'+slug} role="img" aria-label={family+' logo'}>{providerMarks[family]||family.slice(0,1)}</span>}
export default function Page(){const path=usePathname()||'/',[pub,setPub]=useState<Data|null>(null),[me,setMe]=useState<Data|null>(null),[adminData,setAdmin]=useState<Data|null>(null),[loading,setLoading]=useState(true),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[pay,setPay]=useState(10),[search,setSearch]=useState(''),[family,setFamily]=useState('All models'),[sdk,setSdk]=useState('cURL'),[menu,setMenu]=useState(false),[newKey,setNewKey]=useState(''),[keyForm,setKeyForm]=useState(false),[networks,setNetworks]=useState<Data[]>([]),[chainId,setChainId]=useState(4663),[walletOptions,setWalletOptions]=useState<Data[]>([]),[walletPicker,setWalletPicker]=useState(false),[wallet,setWallet]=useState<Data|null>(null),[invoice,setInvoice]=useState<Data|null>(null),[txHash,setTxHash]=useState(''),[providerModels,setProviderModels]=useState<Data[]>([]),[settingsText,setSettingsText]=useState(''),[modelEdit,setModelEdit]=useState<Data|null>(null),[modelText,setModelText]=useState(''),[demoIndex,setDemoIndex]=useState(0),[demoText,setDemoText]=useState('');
const dashboard=['/dashboard','/keys','/usage','/billing','/admin'].includes(path);
const [base,setBase]=useState('https://YOUR_DOMAIN/v1');
useEffect(()=>{setBase(window.location.origin+'/v1')},[]);
useEffect(()=>{let index=0,next:ReturnType<typeof setTimeout>;setDemoText('');const answer=demoSamples[demoIndex].answer;const typing=setInterval(()=>{index+=1;setDemoText(answer.slice(0,index));if(index>=answer.length){clearInterval(typing);next=setTimeout(()=>setDemoIndex(i=>(i+1)%demoSamples.length),2400)}},24);return()=>{clearInterval(typing);clearTimeout(next)}},[demoIndex]);
const snippet=sdk==='Python'?`from openai import OpenAI\nclient = OpenAI(base_url="${base}", api_key="${brand.keyPrefix}…")\nresponse = client.chat.completions.create(\n    model="YOUR_ENABLED_MODEL",\n    messages=[{"role":"user","content":"Hello!"}],\n    max_completion_tokens=256,\n    stream=True\n)\nfor chunk in response:\n    print(chunk.choices[0].delta.content or "", end="")`:sdk==='Node.js'?`import OpenAI from "openai";\nconst client = new OpenAI({\n  baseURL: "${base}",\n  apiKey: process.env.ROUTERS_API_KEY,\n});\nconst stream = await client.chat.completions.create({\n  model: "YOUR_ENABLED_MODEL",\n  messages: [{ role: "user", content: "Hello!" }],\n  max_completion_tokens: 256, stream: true,\n});`:sdk==='Vercel AI SDK'?`import { createOpenAICompatible } from '@ai-sdk/openai-compatible';\nimport { streamText } from 'ai';\nconst routers = createOpenAICompatible({\n  name: '${brand.name}', baseURL: '${base}',\n  apiKey: process.env.ROUTERS_API_KEY,\n});\nconst result = streamText({\n  model: routers('YOUR_ENABLED_MODEL'), prompt: 'Hello!',\n  maxOutputTokens: 256,\n});`:`curl ${base}/chat/completions \\\n  -H "Authorization: Bearer $ROUTERS_API_KEY" \\\n  -H "Content-Type: application/json" \\\n  -d '{"model":"YOUR_ENABLED_MODEL",\n       "messages":[{"role":"user","content":"Hello!"}],\n       "max_completion_tokens":256,"stream":true}'`;
const refresh=async()=>{const results=await Promise.allSettled([call('/api/public'),call('/api/me'),call('/api/payment/networks')]);if(results[0].status==='fulfilled')setPub(results[0].value);else setMessage('Platform data could not be loaded. Refresh to try again.');if(results[1].status==='fulfilled')setMe(results[1].value);else setMe(null);if(results[2].status==='fulfilled')setNetworks(results[2].value);setLoading(false);};
useEffect(()=>{refresh();const listener=(e:any)=>setWalletOptions(prev=>prev.some(x=>x.info.uuid===e.detail.info.uuid)?prev:[...prev,e.detail]);window.addEventListener('eip6963:announceProvider',listener);window.dispatchEvent(new Event('eip6963:requestProvider'));return()=>window.removeEventListener('eip6963:announceProvider',listener);},[]);
useEffect(()=>{if(path==='/admin'&&me?.user.role==='admin')call('/api/admin').then(d=>{setAdmin(d);setSettingsText(JSON.stringify(d.settings,null,2))}).catch(e=>setMessage(e.message));},[path,me]);
async function action(fn:()=>Promise<void>){setMessage('');setBusy(true);try{await fn()}catch(e:any){setMessage(e.message||'Unable to complete this action.')}finally{setBusy(false)}}
function pickNetwork(id:number){setChainId(id);setInvoice(null);setWallet(null);setWalletPicker(false)}
async function connect(selected:Data){await action(async()=>{const sol=chainId===0;let address,signature;const provider=selected.provider;if(sol){const result=await provider.connect();const publicKey=result?.publicKey||provider.publicKey;if(!publicKey)throw new Error('Wallet did not return a Solana address.');address=publicKey.toString();}else{address=(await provider.request({method:'eth_requestAccounts'}))[0];}const c=await call('/api/wallet/challenge',{address,chainId});if(sol){const result=await provider.signMessage(new TextEncoder().encode(c.message),'utf8');const {default:bs58}=await import('bs58');signature=bs58.encode(result.signature||result);}else signature=await provider.request({method:'personal_sign',params:[c.message,address]});await call('/api/wallet/verify',{nonce:c.nonce,signature});setWallet({...selected,address,sol});setWalletPicker(false);await refresh();});}
function availableWallets(){if(chainId!==0)return walletOptions;const w=window as any;return [[w.phantom?.solana,'Phantom'],[w.solflare,'Solflare'],[w.backpack?.solana,'Backpack']].filter(([p])=>p?.connect&&p?.signMessage&&p?.signAndSendTransaction).map(([provider,name])=>({provider,info:{name,uuid:name}}));}
async function purchase(){if(!me){window.location.href='/signin';return;}if(!wallet||wallet.sol!==(chainId===0)){if(chainId!==0&&!walletOptions.length&&(window as any).ethereum)setWalletOptions([{info:{name:'Browser wallet',uuid:'injected'},provider:(window as any).ethereum}]);setWalletPicker(true);return;}await action(async()=>{const data=await call('/api/payments/quote',{pay,chainId});setInvoice(data);setTxHash('');});}
async function sendPayment(){await action(async()=>{if(!wallet||!invoice)throw new Error('Reconnect your payment wallet.');if(new Date(invoice.expires).getTime()<=Date.now())throw new Error('Quote expired. Get a new quote.');let hash;if(invoice.chain_id===0){if(wallet.provider.publicKey?.toString()!==invoice.wallet)throw new Error('Choose the wallet used for this invoice.');const data=await call('/api/payments/solana/transaction',{orderId:invoice.id});const {Transaction}=await import('@solana/web3.js');const transaction=Transaction.from(Uint8Array.from(atob(data.transaction),c=>c.charCodeAt(0)));const result=await wallet.provider.signAndSendTransaction(transaction);hash=typeof result==='string'?result:result.signature;}else{await wallet.provider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x'+invoice.chain_id.toString(16)}]});const accounts=await wallet.provider.request({method:'eth_accounts'});if(accounts[0]?.toLowerCase()!==invoice.wallet)throw new Error('Choose the wallet used for this invoice.');hash=await wallet.provider.request({method:'eth_sendTransaction',params:[{from:invoice.wallet,to:invoice.treasury,value:'0x'+BigInt(invoice.wei).toString(16)}]});}setTxHash(hash);localStorage.setItem('mint_pending_invoice',JSON.stringify({orderId:invoice.id,txHash:hash}));setMessage('Payment submitted. Verify it after network finality.');});}
const u=me?.user,models=pub?.models||[],filtered=models.filter((m:Data)=>(family==='All models'||m.family===family)&&(m.name+' '+m.family).toLowerCase().includes(search.toLowerCase())),active=models.filter((m:Data)=>m.enabled&&m.verified),today=me?.daily.find((d:Data)=>String(d.day).slice(0,10)===new Date().toISOString().slice(0,10)),totalTokens=me?.modelUsage.reduce((n:number,m:Data)=>n+Number(m.actual_tokens),0)||0;
const title=({'/dashboard':'Overview','/keys':'API keys','/usage':'Usage','/billing':'Billing','/admin':'Admin'} as Data)[path];
function calculator(){return <div className="calculator"><div className="row"><span className="eyebrow">YOUR NEXT BUILD STARTS HERE</span><span className="tiny-pill">Pay as you go</span></div><h2>Make your budget<br/>go further.</h2><label className="muted">You pay</label><div className="price-input" aria-label={`You pay ${pay} US dollars`}><span>$</span><strong>{pay}</strong><span>USD</span></div><div className="packages">{brand.packages.map(p=><button className={pay===p.pay?'chosen':''} onClick={()=>{setPay(p.pay);setInvoice(null)}} key={p.pay}>${p.pay}</button>)}</div><div className="credit-reveal"><span>You receive<br/><small>Routers usage credit</small></span><strong>${pay*2}<small>.00</small></strong></div><div className="calc-detail"><span>Base tokens included</span><b>{pub?.baseTokensPerDollar?compact(pay*2*pub.baseTokensPerDollar):'Pricing pending'}</b></div><div className="calc-detail"><span>Subscription fee</span><b>$0</b></div><label className="field">Payment network<select value={chainId} onChange={e=>{pickNetwork(Number(e.target.value))}}><option value={4663}>Robinhood · ETH</option><option value={1}>Ethereum · ETH</option><option value={0}>Solana · SOL</option></select></label><button disabled={busy||!pub?.purchasing} className="button dark full" onClick={purchase}>{pub?.purchasing?(wallet?'Review wallet payment':'Connect wallet'):'Purchases opening soon'} <span>↗</span></button><p className="fine">Pay $10 and receive $20 in usage credit across every available model. Network fees are separate. Confirmed top-ups show your public X handle in the buyer feed.</p></div>}
function compactCalculator(){const selected=brand.packages.find(p=>p.pay===pay)||brand.packages[1];return <div className="calculator compact-calculator"><div className="buy-heading"><h2>Buy API credit</h2><span>Pay as you go</span></div><label>Choose your credit</label><div className="compact-packages" role="group" aria-label="Choose API credit amount">{brand.packages.map(p=><button type="button" aria-pressed={pay===p.pay} className={pay===p.pay?'chosen':''} onClick={()=>{setPay(p.pay);setInvoice(null)}} key={p.pay}><strong>${p.credit}</strong><span>credit</span></button>)}</div><div className="compact-value"><div><span>You pay</span><strong>${selected.pay}</strong></div><span className="value-arrow">→</span><div><span>You get</span><strong>${selected.credit}</strong></div></div><div className="network-tabs" role="group" aria-label="Payment network">{[[1,'Ethereum'],[4663,'Robinhood'],[0,'Solana']].map(([id,name])=><button type="button" key={id} aria-pressed={chainId===id} className={chainId===id?'active':''} onClick={()=>{pickNetwork(Number(id))}}><span>◆</span> {name}</button>)}</div><button className="button lime full" disabled={busy||!pub?.purchasing} onClick={purchase}>{pub?.purchasing?'Buy credits':'Purchases opening soon'} <span>↗</span></button><p className="compact-note">Pay in {chainId===0?'SOL':'ETH'} · Network fees apply · Confirmed top-ups appear in the public buyer feed</p></div>}
function catalogue(limit?:number){const available=filtered.filter((m:Data)=>m.enabled&&m.verified),families=available.filter((m:Data,i:number,a:Data[])=>a.findIndex(x=>x.family===m.family)===i),rest=available.filter((m:Data)=>!families.includes(m)),visible=limit?[...families,...rest].slice(0,limit):filtered;return <div className="model-card-grid">{visible.map((m:Data)=>{const tags=[m.tools&&'Tools',m.vision&&'Vision',m.json_format&&'JSON',m.premium?'Premium':Number(m.ratio)<=.3?'Low cost':'Reasoning'].filter(Boolean).slice(0,3);return <article className="model-card" key={m.id}><div className="model-card-top"><ProviderLogo family={m.family}/><div className="model-card-name"><strong>{m.name}</strong><span>{m.family}</span></div><span className={'availability '+(m.enabled&&m.verified?'live':'')}>{m.enabled&&m.verified?'Live':'Setup'}</span></div><div className="model-tags">{tags.map(tag=><span key={String(tag)}>{tag}</span>)}</div><div className="model-card-meta"><div><span>Output price</span><strong>{m.enabled?'$'+Number(m.output_rate).toFixed(Number(m.output_rate)<.1?3:2)+'/M':'Pending'}</strong></div><div><span>Base-token ratio</span><strong>×{Number(m.ratio)}</strong></div></div></article>})}{!visible.length&&<div className="model-grid-empty"><Empty title={loading?'Loading models…':'No matching models'} text="Try a different model name or provider."/></div>}</div>}
function animatedDemo(){const sample=demoSamples[demoIndex];return <section className="section page-width demo-section"><div className="section-heading"><div><span className="eyebrow">WATCH ONE KEY MOVE</span><h2>A thought, routed<br/>in real time.</h2></div><p>Choose any available model. Routers keeps the same endpoint, key and balance.</p></div><div className="demo-shell"><div className="demo-prompt"><span className="demo-label">Your prompt</span><strong>{sample.prompt}</strong><div className="demo-key"><span>Routers API key</span><code>sk-mint-••••7x9k</code></div><span className="demo-status"><i/> Secure request</span></div><div className="demo-response"><div className="demo-response-head"><span>The answer</span><span className="streaming"><i/> Streaming</span></div><p aria-label={sample.answer}><span aria-hidden="true">{demoText}</span><i className="typing-cursor" aria-hidden="true"/></p><div className="demo-route"><span><ProviderLogo family={sample.family}/><strong>{sample.model}</strong></span><small>Same key · model {demoIndex+1} of {demoSamples.length}</small></div><div className="demo-credit"><span>Pay <strong>$10</strong></span><b>→</b><span>Routers gives you <strong>$20</strong> in API credit</span></div></div></div><div className="demo-dots" aria-label="Choose animated example">{demoSamples.map((item,i)=><button key={item.model} aria-label={'Show '+item.model+' example'} aria-pressed={i===demoIndex} className={i===demoIndex?'active':''} onClick={()=>setDemoIndex(i)}/>)}</div></section>}
function walkthrough(){const steps=[['01','Sign in with X','One click creates your Routers workspace.','/signin','Open workspace'],['02','Top up from a wallet','Choose $10, $20, $50 or $100 in API credit, then pay with SOL or ETH.','/pricing','See pricing'],['03','Create one API key','Copy it once and keep it on your server. Set limits whenever you need them.','/keys','Create a key'],['04','Pick any live model','Use the same endpoint and key. Change only the model ID in your request.','/playground','Try the playground']];return <section className="section page-width walkthrough"><div className="section-heading"><div><span className="eyebrow">FROM ZERO TO FIRST RESPONSE</span><h2>Start building<br/>in four steps.</h2></div><p>No subscription and no new SDK. Bring an OpenAI-compatible client and your wallet.</p></div><div className="walkthrough-grid">{steps.map(([n,title,copy,href,cta])=><article key={n}><span className="step-number">{n}</span><div><h3>{title}</h3><p>{copy}</p><Link href={href}>{cta} <span>↗</span></Link></div></article>)}</div></section>}
function authGate(){return <div className="auth-card"><Tag>YOUR MODEL WORKSPACE</Tag><h1>One account.<br/>A world of models.</h1><p>Sign in with X to manage your API keys, track usage and add credit from your wallet.</p><a className="button dark full" href="/api/auth/x">𝕏 &nbsp; Continue with X <span>↗</span></a>{!pub?.configuration?.x&&<p className="notice">X sign-in is awaiting configuration.</p>}<p className="fine">By continuing, you agree to our <Link href="/terms">Terms</Link> and <Link href="/privacy">Privacy Policy</Link>.</p></div>}
function keys(){return <><div className="page-heading"><div><h1>API keys</h1><p>Separate keys for every project. You control the limits.</p></div><button className="button dark" onClick={()=>setKeyForm(!keyForm)}>+ Create key</button></div>{newKey&&<div className="notice success"><strong>Copy your key now. It will only be shown once.</strong><div className="code-line"><code>{newKey}</code><Copy value={newKey}/></div><button className="text-button" onClick={()=>setNewKey('')}>I saved it · dismiss</button></div>}{keyForm&&<form className="panel form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);action(async()=>{const body={name:f.get('name'),spending_cap:f.get('spending')?Number(f.get('spending'))*1e6:null,token_cap:f.get('tokens')||null,daily_cap:f.get('daily')?Number(f.get('daily'))*1e6:null,monthly_cap:f.get('monthly')?Number(f.get('monthly'))*1e6:null,rpm:Number(f.get('rpm')),expires:f.get('expires')||null,allowed_models:String(f.get('models')||'').split(',').map(x=>x.trim()).filter(Boolean)};const d=await call('/api/keys',body);setNewKey(d.key);setKeyForm(false);await refresh();});}}><label className="field">Key name<input name="name" required maxLength={80} placeholder="My production app"/></label><label className="field">Requests per minute<input name="rpm" type="number" min="1" max="300" defaultValue="30"/></label><label className="field">Lifetime dollar cap<input name="spending" type="number" min="0" step="0.01" placeholder="No cap"/></label><label className="field">Base-token cap<input name="tokens" type="number" min="0" placeholder="No cap"/></label><label className="field">Daily dollar cap<input name="daily" type="number" min="0" step="0.01" placeholder="No cap"/></label><label className="field">Monthly dollar cap<input name="monthly" type="number" min="0" step="0.01" placeholder="No cap"/></label><label className="field">Expires<input name="expires" type="datetime-local"/></label><label className="field">Allowed model IDs<input name="models" placeholder="Comma separated; blank allows all enabled models"/></label><button className="button dark" disabled={busy}>Create API key</button></form>}<div className="panel">{me?.keys.length?me.keys.map((k:Data)=><div className="key-row" key={k.id}><div><strong>{k.name} {k.revoked&&<Tag>Revoked</Tag>}</strong><code>{k.prefix}</code><small>{k.rpm} req/min · {dollars(k.spent_micro)} spent · {compact(k.spent_tokens)} base tokens</small></div>{!k.revoked&&<div className="row"><button className="button small" disabled={busy} onClick={()=>action(async()=>{setNewKey((await call('/api/keys/'+k.id+'/rotate',{})).key);await refresh()})}>Rotate</button><button className="button small" disabled={busy} onClick={()=>action(async()=>{await call('/api/keys/'+k.id+'/revoke',{});await refresh()})}>Revoke</button></div>}</div>):<Empty title="Your first key starts here" text="Create a key to connect your app. Only its hash is stored."/>}</div></>}
function requestTable(){return <div className="panel"><div className="section-title"><h3>Recent requests</h3><span className="muted">Billing metadata only</span></div>{me?.requests.length?<div className="table-scroll"><table><thead><tr><th>Model</th><th>Tokens</th><th>Weighted</th><th>Cost</th><th>Latency</th><th>Status</th></tr></thead><tbody>{me.requests.map((r:Data)=><tr key={r.id}><td>{r.model_id}<small>{new Date(r.created_at).toLocaleString()}</small></td><td>{fmt(r.actual_tokens)}</td><td>{fmt(r.weighted_tokens)}</td><td>{dollars(r.charged_micro)}</td><td>{r.latency_ms} ms</td><td>{r.status}</td></tr>)}</tbody></table></div>:<Empty title="A clear view of every request" text="Model, tokens, cost and timing will appear here after your first API call. Prompt and response text are never stored."/>}</div>}
return <>{path==='/'&&<div className="announcement"><span className="announcement-label">● &nbsp; DOUBLE CREDIT IS LIVE</span><span>Pay $10. Get $20. Pay $50. Get $100.</span><Link href="/pricing">Buy API credit <b>→</b></Link></div>}<header className={path==='/'?"header home-header":"header"}><Logo/><nav className={menu?'nav expanded':'nav'}><Link href="/models">Models</Link><Link href="/pricing">Pricing</Link></nav><div className="header-actions"><Link href={me?'/dashboard':'/signin'} className="button small dark">{me?'Dashboard':'Sign in'} <span>↗</span></Link><button className="menu-button" aria-label="Toggle navigation" onClick={()=>setMenu(!menu)}>☰</button></div></header>
{message&&<div className="toast" role="status"><span>{message}</span><button aria-label="Dismiss message" onClick={()=>setMessage('')}>×</button></div>}
{dashboard?<div className="workspace"><aside className="sidebar"><span className="eyebrow">WORKSPACE</span>{[['/dashboard','◫','Overview'],['/keys','⌘','API keys'],['/usage','▥','Usage'],['/billing','◈','Billing'],['/admin','⚙','Admin']].map(([href,icon,label])=><Link key={href} className={path===href?'selected':''} href={href}><span>{icon}</span>{label}</Link>)}<div className="sidebar-bottom"><Link href="/docs">Read the docs ↗</Link>{u&&<button onClick={()=>action(async()=>{await call('/api/auth/logout',{});await refresh()})}>@{u.username} · Sign out</button>}</div></aside><main className="workspace-main">{!u?(loading?<Empty title="Loading your workspace…" text="Checking your account."/>:authGate()):path==='/keys'?keys():path==='/billing'?<><div className="page-heading"><div><h1>Fuel your next idea.</h1><p>Top up with SOL on Solana or ETH on Ethereum and Robinhood.</p></div><Tag>WALLET PAYMENTS ONLY</Tag></div><div className="billing-grid">{calculator()}<div className="panel"><h3>Purchase history</h3>{me.orders.length?me.orders.map((o:Data)=><div className="purchase-row" key={o.id}><div><strong>${o.pay_usd} → {dollars(o.credit_micro)} credit</strong><small>{o.chain_id===0?'Solana':o.chain_id===1?'Ethereum':'Robinhood'} · {new Date(o.created_at).toLocaleDateString()}</small>{o.tx_hash&&<code>{o.tx_hash.slice(0,16)}…</code>}</div><Tag>{o.state==='pending'&&new Date(o.expires)<new Date()?'Expired':o.state}</Tag></div>):<Empty title="No purchases yet" text="Confirmed wallet payments and your credit history appear here."/>}<details><summary>Already paid but missing credit?</summary><p className="fine">Purchases marked paid are complete. Use this only if you sent a payment and your credit has not appeared.</p><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),orderId=String(f.get('orderId')||'').trim(),txHash=String(f.get('txHash')||'').trim();if(!orderId||!txHash)return;action(async()=>{await call('/api/payments/verify',{orderId,txHash});await refresh();setMessage('Payment confirmed. Your credit balance is up to date.');})}}><label className="field">Invoice ID<input name="orderId" placeholder="Invoice ID from your checkout" required/></label><label className="field">Transaction hash<input name="txHash" placeholder="Transaction hash or Solana signature" required/></label><button className="button" disabled={busy} type="submit">Check submitted payment</button></form></details></div></div></>:path==='/admin'?u.role!=='admin'?<Empty title="Admin access required" text="This area is available to the configured platform administrator."/>:adminData?<><div className="page-heading"><div><h1>Platform controls</h1><p>Configure providers, verify model economics and manage inventory.</p></div><button className="button danger" disabled={busy} onClick={()=>action(async()=>{await call('/api/admin/settings',{shutdown:!adminData.settings.shutdown});await refresh();})}>{adminData.settings.shutdown?'Resume gateway':'Emergency shutdown'}</button></div><div className="metrics"><div className="metric"><span>Physical inventory</span><strong>{compact(adminData.settings.inventory)}</strong><small>weighted base tokens</small></div><div className="metric"><span>Customer commitments</span><strong>{compact(adminData.inventory.committed_tokens)}</strong><small>base tokens</small></div><div className="metric"><span>Credit liability</span><strong>{dollars(adminData.inventory.liability_micro)}</strong><small>usage dollars</small></div></div><div className="panel"><h3>Configuration status</h3><div className="config-grid">{Object.entries(adminData.configuration).map(([k,v])=><div key={k}><code>{k}</code><span className={v?'available':'muted'}>{v?'Configured':'Required'}</span></div>)}</div><p className="fine">Add credentials directly in Railway Variables. Secret values are never displayed here.</p></div><div className="panel"><h3>Providers</h3>{adminData.providers.map((p:Data)=><div className="key-row" key={p.id}><div><strong>{p.name}</strong><code>{p.base_url}</code><small>{p.verified_at?'Connectivity verified':'Awaiting verification'}</small></div><button className="button" disabled={busy} onClick={()=>action(async()=>{const d=await call('/api/admin/providers/'+p.id+'/test',{});setProviderModels(d.models);setMessage(d.models.length+' model IDs discovered.');await refresh()})}>Test connection</button></div>)}{providerModels.length>0&&<details><summary>Discovered upstream model IDs</summary><pre>{providerModels.map(m=>m.id).join('\n')}</pre></details>}<details><summary>Add or rotate a provider</summary><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);action(async()=>{await call('/api/admin/providers',Object.fromEntries(f) as Data);await refresh();setMessage('Provider saved. Test connectivity before use.');})}}><label className="field">Name<input name="name" required/></label><label className="field">Provider ID to rotate<input name="id" placeholder="Leave blank to add"/></label><label className="field">Base URL<input name="base_url" type="url" required placeholder="https://api.example.com/v1"/></label><label className="field">Credential<input name="key" type="password" required autoComplete="off"/></label><label className="field">Priority<input name="priority" type="number" defaultValue="10"/></label><button className="button dark" disabled={busy}>Save encrypted provider</button></form></details></div><div className="panel"><h3>Inventory, purchases and limits</h3><label className="field">Platform settings<textarea rows={16} value={settingsText} onChange={e=>setSettingsText(e.target.value)}/></label><button className="button dark" disabled={busy} onClick={()=>action(async()=>{await call('/api/admin/settings',JSON.parse(settingsText));await refresh();setMessage('Platform settings saved.');})}>Save settings</button></div><div className="panel"><h3>Model pricing and routing</h3><p>Seeded ratios come from the supplied brief. Confirm upstream IDs, prices and capabilities before enabling a model.</p>{adminData.models.map((m:Data)=><div className="admin-model" key={m.id}><span>{m.name}</span><span>×{Number(m.ratio)}</span><span>{m.enabled?'Enabled':'Disabled'}</span><button className="text-button" onClick={()=>{setModelEdit(m);setModelText(JSON.stringify(m,null,2))}}>Configure ↗</button></div>)}</div><div className="panel"><h3>Users</h3>{adminData.users.map((a:Data)=><div className="key-row" key={a.id}><div><strong>@{a.username}</strong><code>{a.id}</code><small>{dollars(a.purchased_micro)} · {compact(a.base_tokens)} base tokens</small></div><button className="button small" disabled={busy} onClick={()=>action(async()=>{await call('/api/admin/users/'+a.id,{suspended:!a.suspended});await refresh()})}>{a.suspended?'Unsuspend':'Suspend'}</button></div>)}</div><div className="panel"><h3>Model economics</h3><p>Usage credit billed and supplier costs are tracked separately. Usage-credit dollars are not cash revenue.</p><div className="table-scroll"><table><thead><tr><th>Model</th><th>Requests</th><th>Usage credit billed</th><th>Supplier cost</th></tr></thead><tbody>{adminData.analytics.map((a:Data)=><tr key={a.model_id}><td>{a.model_id}</td><td>{fmt(a.requests)}</td><td>{dollars(a.revenue_micro)}</td><td>{dollars(a.upstream_micro)}</td></tr>)}</tbody></table></div></div><div className="panel"><h3>Manual credit adjustment</h3><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);action(async()=>{await call('/api/admin/credit',{userId:f.get('userId'),micro:Number(f.get('dollars'))*1e6,baseTokens:Number(f.get('baseTokens')),reference:f.get('reference')});await refresh();setMessage('Backed credit issued.');})}}>{[['userId','User ID'],['dollars','Dollar credit'],['baseTokens','Base tokens'],['reference','Unique adjustment reference']].map(([name,label])=><label className="field" key={name}>{label}<input name={name} required/></label>)}<button className="button" disabled={busy}>Issue backed credit</button></form></div><div className="panel"><h3>Reservations requiring reconciliation</h3>{adminData.reservations.length?adminData.reservations.map((r:Data)=><details key={r.id}><summary>{r.model_id} · {r.state} · {dollars(r.max_micro)}</summary><code>{r.id}</code><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);action(async()=>{await call('/api/admin/reconcile',{requestId:r.id,usage:JSON.parse(String(f.get('usage')))});await refresh();})}}><label className="field">Verified provider usage JSON<textarea name="usage" required placeholder='{"prompt_tokens":0,"completion_tokens":0}'/></label><button className="button" disabled={busy}>Reconcile verified usage</button></form></details>):<p>No unresolved requests.</p>}</div></>:<Empty title="Loading platform controls…" text="Verifying administrator access."/>:<><div className="page-heading"><div><span className="eyebrow">YOUR WORKSPACE</span><h1>{path==='/usage'?'Every token, accounted for.':`Welcome back, ${u.username}.`}</h1><p>{path==='/usage'?'Understand exactly where your credit goes.':'More room for your next idea.'}</p></div><Link className="button dark" href="/billing">Add credit ↗</Link></div><div className="metrics"><div className="metric featured"><span>Total available credit</span><strong>{dollars(Number(u.purchased_micro)+(u.promo_expires&&new Date(u.promo_expires)>new Date()?Number(u.promo_micro):0))}</strong><small>Available prepaid usage credit</small></div><div className="metric"><span>Base tokens remaining</span><strong>{compact(u.base_tokens)}</strong><small>{fmt(u.base_tokens)} purchased base tokens</small></div><div className="metric"><span>Actual model tokens used</span><strong>{compact(totalTokens)}</strong><small>Input, output, cached and reasoning</small></div></div><div className="two-col"><div className="panel"><div className="section-title"><h3>Daily usage</h3><Tag>LAST 30 DAYS</Tag></div>{me.daily.length?<div className="bars">{me.daily.map((d:Data)=><div className="bar-column" key={d.day} title={new Date(d.day).toLocaleDateString()+': '+dollars(d.micro)}><div style={{height:Math.max(2,Number(d.micro)/Math.max(1,...me.daily.map((x:Data)=>Number(x.micro)))*150)+'px'}}/><small>{new Date(d.day).getUTCDate()}</small></div>)}</div>:<Empty title="Ready for your first request" text="Your usage chart will grow as you build."/>}</div><div className="panel"><h3>Today's allowance</h3><div className="allowance"><strong>{compact(Math.max(0,Number(me.dailyLimit)-Number(today?.weighted||0)))}</strong><span>weighted tokens remaining</span></div><progress max={Number(me.dailyLimit)} value={Number(today?.weighted||0)}/><div className="calc-detail"><span>Used today</span><b>{fmt(today?.weighted)}</b></div><div className="calc-detail"><span>Spent today</span><b>{dollars(today?.micro)}</b></div></div></div>{path==='/usage'&&<div className="metrics"><div className="metric"><span>Total base tokens purchased</span><strong>{compact(me.rawPurchased)}</strong><small>Settlement refunds are excluded</small></div><div className="metric"><span>Weighted tokens consumed</span><strong>{compact(me.modelUsage.reduce((n:number,m:Data)=>n+Number(m.weighted_tokens),0))}</strong><small>Actual model tokens × supplier ratio</small></div><div className="metric"><span>Global daily capacity left</span><strong>{compact(Math.max(0,Number(pub?.capacity?.limit||0)-Number(pub?.capacity?.used||0)))}</strong><small>Shared operational allowance</small></div></div>}{path==='/usage'&&<div className="panel"><h3>Model-level usage</h3>{me.modelUsage.length?<div className="table-scroll"><table><thead><tr><th>Model</th><th>Input</th><th>Cached</th><th>Reasoning</th><th>Output</th><th>Weighted</th><th>Cost</th></tr></thead><tbody>{me.modelUsage.map((m:Data)=><tr key={m.model_id}><td>{m.model_id}</td>{['input_tokens','cached_tokens','reasoning_tokens','output_tokens','weighted_tokens'].map(k=><td key={k}>{fmt(m[k])}</td>)}<td>{dollars(m.charged_micro)}</td></tr>)}</tbody></table></div>:<Empty title="No model usage yet" text="Each model’s token types and billing totals will appear here."/>}</div>}{requestTable()}</>}</main></div>:
path==='/'?<main className="reference-home"><div className="marble-edge left" aria-hidden="true"/><div className="marble-edge right" aria-hidden="true"/><section className="hero page-width"><div className="hero-copy"><h1>Pay $10.<br/>Get <mark>$20</mark>.</h1><p>$20 in API credit across every available model.<br/>Pay $50 and get $100.</p><Link className="intro-link" href="/docs">Meet your new API <span>↗</span></Link><Link className="signup-reward" href="/signin"><span className="signup-reward-icon">𝕏</span><span><small>FIRST-TIME SIGNUP REWARD</small><strong>Sign up with X. Get 1M tokens.</strong></span><b>Claim ↗</b></Link><div className="hero-facts"><div><strong>$0</strong><span>subscription or setup fees</span></div><div><strong>2×</strong><span>usage credit on every top-up</span></div></div></div>{compactCalculator()}</section><section className="trust-row page-width">{[['Built for your stack','Use an OpenAI-compatible endpoint with the tools you already know.'],['Pay from your wallet','Top up with SOL on Solana or ETH on Ethereum and Robinhood. Use credit as you go.'],['Your prompts stay yours','We store usage metadata, never the text of your prompts or responses.']].map(([title,copy])=><article key={title}><h3>{title}</h3><p>{copy}</p></article>)}</section>{animatedDemo()}<section className="providers-section page-width"><h2>One connection. More possibilities.</h2><div className="provider-names">{['OpenAI','Anthropic','Google','xAI','DeepSeek','Qwen'].map(x=><strong key={x}>{x}</strong>)}</div></section><section className="section page-width"><div className="section-heading"><div><span className="eyebrow">THE MODEL COLLECTION</span><h2>The right mind<br/>for every idea.</h2></div><Link href="/models" className="button">Explore all models ↗</Link></div>{catalogue(9)}<p className="fine">Model availability and pricing are shown after provider verification. Unverified models cannot receive requests.</p></section>{walkthrough()}<section className="section page-width pulse-grid"><div className="panel capacity"><div className="section-title"><h3>Platform capacity</h3><Tag>{pub?.configuration?.upstream?'CONNECTED':'PREPARING TO LAUNCH'}</Tag></div><strong>{pub?.capacity?compact(Math.max(0,Number(pub.capacity.limit)-Number(pub.capacity.used))):'—'}</strong><p>weighted tokens in today's operating allowance</p><progress max={Number(pub?.capacity?.limit||100)} value={Number(pub?.capacity?.used||0)}/><div className="calc-detail"><span>Used today</span><b>{fmt(pub?.capacity?.used)}</b></div><div className="calc-detail"><span>Verified active models</span><b>{active.length}</b></div></div><div className="panel buyer-panel"><div className="section-title"><h3>Who bought credit</h3><span className="live-label"><i/> LIVE</span></div><p className="buyer-intro">Verified wallet top-ups from the Routers community.</p>{pub?.purchases?.length?<div className="buyer-list">{pub.purchases.map((p:Data,i:number)=><div className="buyer-row" key={p.username+p.confirmed_at+i}><a className="buyer-identity" href={`https://x.com/${p.username}`} target="_blank" rel="noreferrer"><span className="buyer-avatar">{String(p.username||'?').slice(0,1).toUpperCase()}</span><span><strong>@{p.username}</strong><small>{p.chain_id===0?'Solana':p.chain_id===1?'Ethereum':'Robinhood'} · {new Date(p.confirmed_at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</small></span></a><span className="buyer-value"><strong>{dollars(p.credit_micro)} credit</strong><small>paid ${p.pay_usd}</small></span></div>)}</div>:<Empty title="The first chapter is yours." text="Verified wallet purchases will appear here with the buyer's public X handle. Wallet addresses stay private."/>}<p className="buyer-privacy">Public X handles only · Wallet addresses and transaction hashes are hidden</p></div></section><section className="migration page-width"><div><Tag>SMALL CHANGE. BIG POSSIBILITIES.</Tag><h2>Two lines.<br/>You're connected.</h2><p>Point your compatible client to Routers.<br/>Your app keeps moving.</p><Link className="button" href="/docs">Read the documentation ↗</Link></div><div className="code-window"><div className="code-title"><span>.env</span><Copy value={`OPENAI_BASE_URL=${base}\nOPENAI_API_KEY=${brand.keyPrefix}…`}/></div><pre><span className="code-comment"># Your new connection</span>{`\nOPENAI_BASE_URL=${base}\nOPENAI_API_KEY=${brand.keyPrefix}…`}</pre><div className="code-bottom">OpenAI-compatible · Streaming · Model routing</div></div></section><section className="faq page-width"><span className="eyebrow">A FEW GOOD QUESTIONS</span><h2>Simple by design.</h2>{[['What am I buying?','Prepaid dollar-denominated API usage credit, with a separately tracked base-token allowance. Both limits apply.'],['How do base tokens work?','Each model consumes base tokens at its configured supplier ratio. One actual model token can consume less or more than one base token. Your dashboard shows both counts.'],['Can I pay with my wallet?','Yes. Wallet checkout supports native SOL on Solana and ETH on Ethereum and Robinhood. Credit is added after the server verifies the transaction and its finality. Purchased credit works across all available models, including premium models.'],['Do you store prompts or responses?','No. The gateway stores billing metadata: model, token counts, cost, status and timing. The upstream provider processes request content under its own policies.'],['Can one key use every model?','Yes. One Routers key works across every currently enabled model available to that key, including GPT, Claude, Gemini, Grok, DeepSeek, Qwen and other listed families. Change only the model ID in your request.']].map(([q,a])=><details key={q}><summary>{q}<span>+</span></summary><p>{a}</p></details>)}</section></main>:
path==='/signin'?<main className="signin page-width">{authGate()}</main>:
path==='/models'?<main className="page-width inner-page"><Tag>THE MODEL COLLECTION</Tag><h1>Find your next<br/><span className="accent-text">thinking partner.</span></h1><p className="lead">One API. A growing catalogue of intelligence.</p><div className="catalogue-controls"><input aria-label="Search models" placeholder="Search models or providers…" value={search} onChange={e=>setSearch(e.target.value)}/><select aria-label="Filter provider" value={family} onChange={e=>setFamily(e.target.value)}>{['All models',...Array.from(new Set<string>(models.map((m:Data)=>m.family)))].map(f=><option key={f}>{f}</option>)}</select><span>{filtered.length} models · {active.length} verified live</span></div>{catalogue()}<p className="fine">Ratios are initial supplier settings awaiting verification. Output rates are usage-credit dollars per million tokens; your effective cash rate depends on the package purchased.</p></main>:
path==='/pricing'?<main className="page-width inner-page"><Tag>MORE ROOM TO BUILD</Tag><h1>A little budget.<br/>A lot of possibility.</h1><p className="lead">No subscriptions. No monthly commitments. Just credit.</p><div className="pricing-layout">{calculator()}<div><div className="panel"><h3>Your budget, compared</h3><div className="compare-label"><span>Cash paid</span><b>${pay}</b></div><div className="compare-bar" style={{width:'50%'}}/><div className="compare-label"><span>Routers usage credit</span><b>${pay*2}</b></div><div className="compare-bar mint"/><p>Twice the usage credit on every top-up. $1 credit covers 1M base tokens; model multipliers determine consumption.</p></div><div className="panel"><h3>Understand your balance</h3><p><strong>Dollar credit</strong> pays for input, cached, reasoning and output tokens at each model's rates.</p><p><strong>Base tokens</strong> measure supplier capacity. Model ratios determine how quickly this allowance is used.</p><p><strong>Actual tokens</strong> show the tokens your models processed, without weighting.</p></div></div></div></main>:
path==='/docs'?<main className="page-width inner-page docs"><Tag>BUILT FOR BUILDERS</Tag><h1>Make your first call.</h1><p className="lead">One Routers key. Every model available to that key.</p><div className="panel"><h3>1. Create your API key</h3><p>Sign in with X, add credit and create one key in your workspace. The same key and balance work across all enabled model families. Keep the key on your server.</p><Link href="/keys" className="button">Open API keys ↗</Link></div><div className="panel"><h3>2. Choose any available model</h3><p>OpenAI-compatible describes the request format. It does not limit you to OpenAI models. Use the same <code>https://routers.markets/v1</code> base URL and Routers key for available GPT, Claude, Gemini, Grok, DeepSeek, Qwen and other models; change only the <code>model</code> value.</p><p>Call <code>GET /v1/models</code> with your API key to get the exact model IDs allowed for that key.</p><Link href="/playground" className="button">Test a model in the Playground ↗</Link></div><div className="code-window"><div className="code-title"><div className="sdk-tabs">{['cURL','Python','Node.js','Vercel AI SDK'].map(s=><button className={s===sdk?'active':''} onClick={()=>setSdk(s)} key={s}>{s}</button>)}</div><Copy value={snippet}/></div><pre>{snippet}</pre></div><div className="panel"><h3>How usage works</h3><p>Before forwarding a request, we reserve its maximum estimated dollar cost and weighted base-token cost. After the provider returns usage, the difference is released. Keep <code>max_completion_tokens</code> close to what you need.</p><p>Incomplete streams or missing provider usage retain their reservation until reconciliation. This protects your balance from inaccurate billing.</p><table><thead><tr><th>Response</th><th>Meaning</th></tr></thead><tbody>{[['401','Missing, expired or revoked API key'],['402','Insufficient credit or per-key cap'],['429','Request, concurrency or daily capacity limit'],['503','Provider, inventory or configuration unavailable']].map(([a,b])=><tr key={a}><td>{a}</td><td>{b}</td></tr>)}</tbody></table></div><div className="notice">Native Anthropic and Claude Agent SDK adapters are not yet verified. Use the OpenAI-compatible endpoint. SDK examples require live integration testing before production use.</div></main>:
path==='/status'?<main className="page-width inner-page"><Tag>PLATFORM STATUS</Tag><h1>Clarity, in real time.</h1><p className="lead">Current configuration and measured API activity.</p><div className="panel status-list">{[['Web application',true],['Database',pub?.configuration?.database],['Upstream provider',pub?.configuration?.upstream],['X authentication',pub?.configuration?.x],['Wallet checkout',pub?.purchasing]].map(([name,ready])=><div className="status-row" key={String(name)}><span>{name}</span><Tag>{ready?'Ready':'Awaiting configuration'}</Tag></div>)}</div><div className="metrics"><div className="metric"><span>Requests in 24 hours</span><strong>{fmt(pub?.stats?.requests)}</strong></div><div className="metric"><span>Average request duration</span><strong>{pub?.stats?.latency?pub.stats.latency+' ms':'Not measured'}</strong></div><div className="metric"><span>Gateway</span><strong>{pub?.shutdown?'Paused':'Available'}</strong></div></div></main>:
['/terms','/privacy','/acceptable-use'].includes(path)?<main className="page-width inner-page legal"><Tag>THE DETAILS</Tag><h1>{path==='/terms'?'Terms of use':path==='/privacy'?'Privacy policy':'Acceptable use'}</h1>{path==='/terms'?<><p>Routers provides prepaid access to configured third-party AI models. Dollar credit and base-token allowances are separate limits. Displayed rates and permitted models govern each request.</p><h3>Payments and credit</h3><p>Wallet payments must use the receiving address, network and exact amount shown on a valid invoice. Credit is issued after verified on-chain finality. Credit is access to a service, is not transferable and is not redeemable as an investment. Confirmed top-ups appear in the public activity feed with the buyer's X handle, amount, network and confirmation time.</p><h3>Availability</h3><p>Capacity, rate limits and provider availability apply. Models under verification are unavailable. Pricing varies by model and package.</p><h3>Payment errors</h3><p>Retain your invoice ID and transaction hash. Incorrect or late transactions require manual review. On-chain refunds, when approved, require a separately signed treasury transaction.</p></>:path==='/privacy'?<><p>We store your X account ID and username, payment wallet, transaction references, hashed customer API keys, balances and billing metadata. We do not store prompt or generated response text.</p><h3>Public purchase activity</h3><p>After a successful top-up, the public activity feed shows your X username, amount paid, credit received, payment network and confirmation time. It does not show wallet addresses or transaction hashes.</p><h3>Providers</h3><p>Requests are sent to the configured upstream AI provider. That provider processes request content according to its own terms and privacy practices. Payment transactions are public blockchain records.</p><h3>Account security</h3><p>We use session cookies and limited security identifiers to authenticate your workspace and protect the service from abuse.</p><h3>Credential security</h3><p>Upstream keys are encrypted at rest. Customer keys are stored as hashes and are shown in full only when created or rotated.</p></>:<><p>Use Routers only for lawful activities consistent with the selected model provider's policies.</p><h3>Protect accounts and capacity</h3><p>Do not attempt to bypass rate limits, use stolen payment credentials, compromise accounts or interfere with the service.</p><h3>Protect others</h3><p>Do not use the service to exploit children, distribute malware, commit fraud or cause harm. Accounts and keys may be suspended for abuse.</p></>}</main>:<main className="page-width inner-page"><h1>Page not found.</h1><Link className="button" href="/">Back to Routers ↗</Link></main>}
{!dashboard&&<footer className="footer page-width"><div><Logo/><p>More intelligence. Less spend.</p></div><nav><Link href="/docs">Developers</Link><Link href="/playground">Playground</Link><Link href="/status">Status</Link><Link href="/terms">Terms</Link><Link href="/privacy">Privacy</Link><Link href="/acceptable-use">Acceptable use</Link></nav><small>© {new Date().getFullYear()} {brand.name}</small></footer>}
{walletPicker&&<div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true" aria-labelledby="wallet-title"><button className="close" aria-label="Close wallet selection" onClick={()=>setWalletPicker(false)}>×</button><Tag>YOUR WALLET. YOUR CREDIT.</Tag><h2 id="wallet-title">Connect a wallet</h2><p>Sign a message to link your payment wallet. No transaction is made at this step.</p>{availableWallets().length?availableWallets().map(w=><button className="wallet-option" key={w.info.uuid} disabled={busy} onClick={()=>connect(w)}>{w.info.name}<span>↗</span></button>):<p className="notice">{chainId===0?'Open this site in Phantom’s in-app browser, or install Phantom, Solflare or Backpack.':'Open this site in MetaMask or Trust Wallet’s in-app browser, or install an Ethereum-compatible browser wallet.'}</p>}</div></div>}
{invoice&&<div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true" aria-labelledby="invoice-title"><button className="close" aria-label="Close payment review" onClick={()=>setInvoice(null)}>×</button><Tag>REVIEW YOUR PAYMENT</Tag><h2 id="invoice-title">${pay*2} in API credit.</h2><p>{invoice.amount||invoice.eth} {invoice.symbol||'ETH'} · {invoice.chain_id===0?'Solana':invoice.chain_id===1?'Ethereum':'Robinhood'}</p><div className="notice"><strong>Receiving wallet</strong><code>{invoice.treasury}</code></div><p className="fine">Invoice {invoice.id}<br/>Quote expires {new Date(invoice.expires).toLocaleTimeString()}. Your wallet shows network fees before you approve.</p>{txHash?<><code className="break">{txHash}</code><button className="button dark full" disabled={busy} onClick={()=>action(async()=>{await call('/api/payments/verify',{orderId:invoice.id,txHash});setInvoice(null);await refresh();setMessage('Payment confirmed. Your credit is ready.');})}>Verify confirmed payment</button></>:<button className="button dark full" disabled={busy} onClick={sendPayment}>Continue in wallet ↗</button>}</div></div>}
{modelEdit&&<div className="modal-backdrop"><div className="modal wide" role="dialog" aria-modal="true" aria-labelledby="model-title"><button className="close" aria-label="Close model editor" onClick={()=>setModelEdit(null)}>×</button><h2 id="model-title">{modelEdit.name}</h2><p>Rates are usage-credit dollars per million tokens. Only enable models whose IDs, rates and capabilities you verified.</p><label className="field">Model configuration<textarea rows={20} value={modelText} onChange={e=>setModelText(e.target.value)}/></label><button className="button dark" disabled={busy} onClick={()=>action(async()=>{await call('/api/admin/models/'+modelEdit.id,JSON.parse(modelText));setModelEdit(null);await refresh();setMessage('Model settings saved.');})}>Save model</button></div></div>}
</>}
